// NPC永久来源严格绑定实际答复与本人原已收申请；不能把缺玩家回执当成NPC。
#include "political_office_resignation_authored.hpp"
namespace hanmo::resident {namespace {
Status origin(const PoliticalOfficeResignationResponseCatalog& c,const PoliticalOfficeResignationAuthoredOrigin& o,const PoliticalOfficeResignationRequest& r,const StableId& actor){const auto* i=c.intents.find(o.intent_id);return c.version==1&&i&&i->id==o.intent_id&&o.actor_id==actor&&actor==i->approver_actor_id&&actor==r.approver_actor_id&&r.policy_id==i->resignation_policy_id&&o.director_policy_id==i->director_policy_id&&o.request_fact_id==r.id?common_success():common_failure("OfficeResignationResponseOriginMismatch",r.id);}
}
Status validate_political_office_resignation_authored_command(const CommonStore& common,const OrganizationState& organizations,const OrganizationCatalog& org,const PoliticalOfficeResignationState& state,const PoliticalOfficeResignationResponseCatalog& catalog,const PoliticalOfficeResignationAuthoredOrigin& o,const StableId& actor,const PoliticalOfficeResignationCommand& command){const auto* c=std::get_if<PoliticalAnswerOfficeResignation>(&command);const auto* r=c?state.requests.find(c->request_fact_id):nullptr;if(state.version!=2||actor==common.state().metadata.player_actor_id||!c||!r||c->authority.actor_id!=actor)return common_failure("OfficeResignationResponseCommandRequired");auto v=origin(catalog,o,*r,actor);if(!v.ok)return v;auto decision=read_political_office_resignation_response_decision(common,organizations,org,*r,*catalog.intents.find(o.intent_id),common.tick());if(!decision.ok)return {false,{},decision.error};return decision.value.accept==c->accept&&decision.value.reason==o.reason?common_success():common_failure("OfficeResignationResponseReasonMismatch",r->id);}
Status validate_political_office_resignation_authored_source(const CommonStore& common,const OrganizationState& organizations,const OrganizationCatalog& org,const PoliticalOfficeResignationState& state,const PoliticalOfficeResignationResponseCatalog& catalog,const StableId& id,const PoliticalSuccessionPlayerRead& player){const auto* a=state.answers.find(id);const auto* o=state.authored_origins.find(id);const auto* r=a?state.requests.find(a->request_fact_id):nullptr;if(state.version!=2||!a||a->id!=id||!o||!r||a->player_receipt||!player||!political_office_resignation_fact_sequence(common,id,"political_office_resignation_answered"))return common_failure("OfficeResignationResponseActualSourceRequired",id);auto v=origin(catalog,*o,*r,a->actor_id);if(!v.ok)return v;auto decision=read_political_office_resignation_response_decision(common,organizations,org,*r,*catalog.intents.find(o->intent_id),a->tick,id);if(!decision.ok)return {false,{},decision.error};if(decision.value.accept!=a->accepted||decision.value.reason!=o->reason)return common_failure("OfficeResignationResponseReasonMismatch",id);auto who=player(a->tick,id);if(!who.ok)return {false,{},who.error};return !who.value.empty()&&common.actor(who.value)&&common.actor(a->actor_id)&&who.value!=a->actor_id?common_success():common_failure("OfficeResignationResponseHistoricalNonPlayerRequired",id);}
}
